var __idRegexCache = {};
function wordRegex(name) {
  if (!__idRegexCache[name]) {
    __idRegexCache[name] = new RegExp("\\b" + name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "\\b");
  }
  return __idRegexCache[name];
}

